export function packingFailures(radii, inputId) {
  const sorted = [...radii].sort((a, b) => a - b);
  const failures = [];
  const reject = (code, requested, bound) =>
    failures.push({
      code,
      inputId,
      minimumRequiredPairDistance: requested,
      maximumPossibleMinimumDistance: bound,
    });
