  return {
    revision: FIELD_REVISION,
    owners,
    input,
    evaluate: (point) => evaluateWithOwner(point).value,
    raw: (point) => {
      const result = evaluateWithOwner(point);
      return { ...result, value: Math.round(result.value * TICKS) };
    },
  };
}

