      { kind: 'lobe', start: 20 * 3, end: 24 * 3, far: [21 * 3, 23 * 3], disk: [-0.1, -0.53] },
      { kind: 'peninsula', start: 7 * 3, end: 12 * 3, far: [8 * 3, 11 * 3], disk: [0.25, 0.535] },
