    bay: { start: 0, end: 4 * 3, witness: [0.45, -0.15] },
    interiorWitness: [0, 0],
    islandAnchors: [5 * 3, 6 * 3, 15 * 3, 16 * 3, 21 * 3, 22 * 3],
