    const role = {
      id: attachment.id,
      kind: attachment.kind,
      area: polygonArea(attachment.polygon) / SPHERE,
      share: polygonArea(attachment.polygon) / bodyPlanar,
      widthLower,
      widthUpper,
      firstDiskRadiusLower: diskRadius,
    };
