  const side = (p) => ((b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])) / width;
  const positive = (p, code, id) => {
    const value = side(p);
    if (!Number.isFinite(value) || value <= EPS)
      reject(code, value, '> EPS on the origin side of the chord', id);
    return value;
